const crypto = require('crypto');

function redactPII(event, salt) {
  if (event.user_id) {
    event.user_id = crypto.createHash('sha256')
      .update(event.user_id + salt)
      .digest('hex');
  }
  if (event.device_id) {
    event.device_id = crypto.createHash('sha256')
      .update(event.device_id + salt)
      .digest('hex');
  }
  return event;
}
```

## Why This Is Asked

